/* From Uiverse.io by G4b413l - Tags: switch */
.__UIV_SCOPE__ .switch input {
 display: none;
}

.__UIV_SCOPE__ .switch {
 width: 60px;
 height: 30px;
 position: relative;
}

.__UIV_SCOPE__ .slider {
 position: absolute;
 top: 0;
 bottom: 0;
 left: 0;
 right: 0;
 border-radius: 30px;
 box-shadow: 0 0 0 2px #777, 0 0 4px #777;
 cursor: pointer;
 border: 4px solid transparent;
 overflow: hidden;
 transition: 0.2s;
}

.__UIV_SCOPE__ .slider:before {
 position: absolute;
 content: "";
 width: 100%;
 height: 100%;
 background-color: #777;
 border-radius: 30px;
 transform: translateX(-30px);
 /*translateX(-(w-h))*/
 transition: 0.2s;
}

.__UIV_SCOPE__ input:checked + .slider:before {
 transform: translateX(30px);
 /*translateX(w-h)*/
 background-color: limeGreen;
}

.__UIV_SCOPE__ input:checked + .slider {
 box-shadow: 0 0 0 2px limeGreen, 0 0 8px limeGreen;
}

.__UIV_SCOPE__ .switch200 .slider:before {
 width: 200%;
 transform: translateX(-82px);
 /*translateX(-(w-h))*/
}

.__UIV_SCOPE__ .switch200 input:checked + .slider:before {
 background-color: red;
}

.__UIV_SCOPE__ .switch200 input:checked + .slider {
 box-shadow: 0 0 0 2px red, 0 0 8px red;
}
